package com.library.controller; import com.library.common.model.ApiResult; import com.library.common.model.LoginUser; import com.library.model.dto.LoginDTO; import com.library.model.vo.LoginVO; import com.library.service.AuthService; import com.library.util.UserContext; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService service; public AuthController(AuthService service){this.service=service;} @PostMapping("/login") public ApiResult<LoginVO> login(@Valid @RequestBody LoginDTO dto){return ApiResult.success(service.login(dto));} @PostMapping("/logout") public ApiResult<Void> logout(){return ApiResult.success();} @GetMapping("/me") public ApiResult<LoginUser> me(){return ApiResult.success(UserContext.get());} }
